 */
public object FfiConverterTypeRejectReason: FfiConverterRustBuffer<RejectReason> {
    override fun read(buf: ByteBuffer) = try {
        RejectReason.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: RejectReason) = 4UL

    override fun write(value: RejectReason, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





/**
 * "What's tricky about it" — the *nature* of the difficulty, never its magnitude.
 */

enum class Tag {
    
    /**
     * The sounds are the problem.
     */
    PRON,
    /**
     * The meaning won't stick.
     */
    REMEMBER,
    /**
     * "I will definitely need this."
     */
    USEFUL,
    /**
     * Specific lexical items trip me up.
     */
    WORDS;

    


    companion object
}


