/**
 * The outcome of scoring a take.
 */
sealed class TakeResult {
    
    /**
     * A real score.
     */
    data class Scored(
        /**
         * 40..99.
         */
        val `overall`: kotlin.UByte, 
        /**
         * Per-syllable accuracy, 40..99.
         */
        val `syllables`: kotlin.ByteArray, 
        /**
         * The learner's normalised contour, for display and the sparkline.
         */
        val `contour`: List<kotlin.Float>, 
        /**
         * Index of the weakest syllable.
         */
        val `worstSyllable`: kotlin.UInt, 
        /**
         * Which feedback template to show.
         */
        val `fixCode`: kotlin.String) : TakeResult()
        
    {
        

        companion object
    }
    
    /**
     * Not scorable. The UI says so honestly.
     */
    data class Rejected(
        /**
         * Why.
         */
        val `reason`: uniffi.loro_core.RejectReason) : TakeResult()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeTakeResult : FfiConverterRustBuffer<TakeResult>{
    override fun read(buf: ByteBuffer): TakeResult {
        return when(buf.getInt()) {
            1 -> TakeResult.Scored(
                FfiConverterUByte.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterSequenceFloat.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> TakeResult.Rejected(
                FfiConverterTypeRejectReason.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: TakeResult): ULong = when(value) {
        is TakeResult.Scored -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUByte.allocationSize(value.`overall`)
                + FfiConverterByteArray.allocationSize(value.`syllables`)
                + FfiConverterSequenceFloat.allocationSize(value.`contour`)
                + FfiConverterUInt.allocationSize(value.`worstSyllable`)
                + FfiConverterString.allocationSize(value.`fixCode`)
            )
        }
        is TakeResult.Rejected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeRejectReason.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: TakeResult, buf: ByteBuffer) {
        when(value) {
            is TakeResult.Scored -> {
                buf.putInt(1)
                FfiConverterUByte.write(value.`overall`, buf)
                FfiConverterByteArray.write(value.`syllables`, buf)
                FfiConverterSequenceFloat.write(value.`contour`, buf)
                FfiConverterUInt.write(value.`worstSyllable`, buf)
                FfiConverterString.write(value.`fixCode`, buf)
                Unit
            }
            is TakeResult.Rejected -> {
                buf.putInt(2)
                FfiConverterTypeRejectReason.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






/**
 * @suppress
 */
public object FfiConverterOptionalUInt: FfiConverterRustBuffer<kotlin.UInt?> {
    override fun read(buf: ByteBuffer): kotlin.UInt? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterUInt.read(buf)
    }

    override fun allocationSize(value: kotlin.UInt?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterUInt.allocationSize(value)
        }
    }

    override fun write(value: kotlin.UInt?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterUInt.write(value, buf)
        }
    }
}




