    uniffiRustCall() { _status ->
    UniffiLib.uniffi_loro_core_fn_func_streak(
    
        
        FfiConverterSequenceString.lower(`practiceDays`),
        FfiConverterString.lower(`today`),_status)
}
    )
    }
    

